async function main(ctx) {
  const input = ctx.input || {};
  const datasetIdOrSlug = typeof input.datasetIdOrSlug === 'string' ? input.datasetIdOrSlug.trim() : '';
  if (!datasetIdOrSlug) throw new Error('datasetIdOrSlug is required');

  const title = typeof input.title === 'string' ? input.title.trim() : '';
  const description = typeof input.description === 'string' ? input.description.trim() : '';

  return {
    widgetType: 'dataset_card',
    props: {
      id: 'dataset:' + datasetIdOrSlug,
      datasetIdOrSlug,
      ...(title ? { title } : {}),
      ...(description ? { description } : {})
    }
  };
}
